**Current Sources/MyApp/AuthManager.swift:**
```swift
import Auth0
import Foundation

class AuthManager {
    let credentialsManager = CredentialsManager(authentication: Auth0.authentication())

    func login(completion: @escaping (Result<Credentials, Error>) -> Void) {
        Auth0
            .webAuth()
            .scope("openid profile email offline_access")
            .audience("https://api.example.com")
            .start { result in
                switch result {
                case .success(let credentials):
                    _ = self.credentialsManager.store(credentials: credentials)
                    completion(.success(credentials))
                case .failure(let error):
                    completion(.failure(error))
                }
            }
    }

    func logout(completion: @escaping (Result<Void, Error>) -> Void) {
        Auth0
            .webAuth()
            .clearSession(federated: false) { result in
                switch result {
                case .success:
                    _ = self.credentialsManager.clear()
                    completion(.success(()))
                case .failure(let error):
                    completion(.failure(error))
                }
            }
    }

    func getCredentials(completion: @escaping (Result<Credentials, Error>) -> Void) {
        credentialsManager.credentials { error, credentials in
            if let credentials = credentials {
                completion(.success(credentials))
            } else {
                completion(.failure(error ?? NSError(domain: "auth0", code: -1)))
            }
        }
    }
}
